#define NOMINMAX
#include "engine.hpp"
#include <iostream>
int main(){std::thread readerThread(engine);defense::Reader reader;for(int n=0;n<4;n++){Sleep(500);double start=now();auto f=reader.read(start);std::cout<<"read_ms="<<(now()-start)*1000<<" valid="<<f.scene.valid<<" grounded="<<f.scene.grounded<<" rigs="<<f.scene.actors.size()<<" balls="<<f.scene.balls.size()<<" geometry="<<reader.geometry.size()<<" goal="<<f.scene.own.goalValid<<" floor="<<f.scene.floor<<" matchKnown="<<f.scene.playingKnown<<" detail="<<f.detail<<"\n";if(n==0){for(auto&g:reader.geometry){auto p=reader.position(g.primitive);auto size=rd<defense::Vec>(reader.h,g.primitive+Offsets::Primitive::Size);std::cout<<" size="<<size.x<<","<<size.y<<","<<size.z<<" board="<<g.board<<" p="<<p.x<<","<<p.y<<","<<p.z<<"\n";}if(!reader.items.empty()){auto item=reader.items.front();for(auto c:children(reader.h,item.id)){std::cout<<" child="<<nm(reader.h,c)<<" class="<<defense::classOf(reader.h,c)<<"\n";if(nm(reader.h,c)=="Attributes")for(auto a:children(reader.h,c))std::cout<<" attr="<<nm(reader.h,a)<<" class="<<defense::classOf(reader.h,a)<<"\n";}}}}running=false;readerThread.join();}
